const context = options.contextData;
const viewmodel = context.viewmodel;
const characterHelper = context.characterHelper;
const resultSettings = {
	hidden: true
};

if (!characterHelper) {
	require(['TDF/Scripts/Aras/Client/Controls/TechDoc/Helper/CharacterHelper'], CharacterHelper => {
		context.characterHelper = new CharacterHelper({viewmodel: viewmodel});
	});
} else if (context.isEditMode) {
	const viewmodel = context.viewmodel;
	const modelCursor = viewmodel.Cursor();
	const selectedElement = context.selectedElement;
	const editLevel = context.documentationEnums.EditLevels.FullAllow;

	if (selectedElement && viewmodel.IsEqualEditableLevel(editLevel)) {
		const isCursorInText = selectedElement.is('ArasTextXmlSchemaElement') && selectedElement === modelCursor.commonAncestor;

		resultSettings.hidden = !isCursorInText;
	}
}

return resultSettings;
